<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Invoice</title><link rel="stylesheet" href="<?=base_url('styles.css')?>"><style>body{background:#090b0d;color:#eee}.wrap{max-width:1180px;margin:auto;padding:30px}.top{display:flex;justify-content:space-between}.card{margin-top:18px;padding:22px;border:1px solid #2b2b2b;border-radius:18px;background:#111416}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.field label{display:block;font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:#999;margin-bottom:6px}.field input,.field textarea,.field select{width:100%;padding:11px;border-radius:8px;border:1px solid #333;background:#0d0f10;color:#eee}.field textarea{min-height:90px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:8px;border-bottom:1px solid #292929}.table input{width:100%;padding:9px;background:#0d0f10;color:#eee;border:1px solid #333;border-radius:7px}.btn{padding:10px 14px;border-radius:9px;border:1px solid #4b4337;background:#181715;color:#e8d4ac;cursor:pointer;text-decoration:none}.primary{background:#c6a66e;color:#111}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}@media(max-width:800px){.grid{grid-template-columns:1fr}.wrap{padding:15px}}</style></head><body><div class="wrap"><div class="top"><div><div style="color:#c8a66e;font-size:11px;letter-spacing:.15em">LEX FACTUM · BILLING</div><h1 style="font:500 40px Georgia,serif">Create Invoice</h1></div><a class="btn" href="<?=site_url('admin/invoices')?>">← Invoices</a></div><form method="post" action="<?=site_url('admin/invoices/store')?>"><?=csrf_field()?><div class="card"><div class="grid"><div class="field"><label>Invoice number</label><input name="invoice_no" placeholder="Auto generated"></div><div class="field"><label>Invoice date</label><input type="date" name="invoice_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Due date</label><input type="date" name="due_date"></div><div class="field"><label>Portal client</label><select id="user" name="user_id"><option value="">No linked account</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" data-name="<?=esc($u['name'])?>" data-email="<?=esc($u['email'])?>"><?=esc($u['name'])?> · <?=esc($u['email'])?></option><?php endforeach;?></select></div><div class="field"><label>Client name</label><input id="name" name="client_name" required></div><div class="field"><label>Email</label><input id="email" name="client_email" type="email"></div><div class="field"><label>Address</label><textarea name="client_address"></textarea></div><div class="field"><label>Phone</label><input name="client_phone"></div><div class="field"><label>Case / matter reference</label><input name="case_reference"></div><div class="field"><label>Advocate</label><input name="advocate_name" value="Ankit Gupta"></div></div></div><div class="card"><div style="display:flex;justify-content:space-between"><h2 style="font:500 25px Georgia,serif">Professional charges</h2><button class="btn" type="button" id="add">+ Add line</button></div><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px"><label style="display:flex;gap:7px;align-items:center;color:#c8a66e;font-size:13px"><input type="checkbox" id="flatMode" name="flat_mode" value="1"> Flat / manual bill mode</label><span style="font-size:12px;color:#888">Use this when you want to enter the final charge directly instead of Qty × Rate.</span></div><table class="table"><thead><tr><th>Description</th><th style="width:100px">Qty</th><th style="width:140px">Rate</th><th style="width:140px">Manual Amount</th><th style="width:120px">Amount</th><th></th></tr></thead><tbody id="rows"><tr><td><input name="description[]" required></td><td><input class="q" name="quantity[]" type="number" min=".01" step=".01" value="1"></td><td><input class="r" name="rate[]" type="number" min="0" step=".01" value="0"></td><td><input class="m" name="manual_amount[]" type="number" min="0" step=".01" placeholder="e.g. 50000"></td><td class="a">0.00</td><td><button class="btn del" type="button">×</button></td></tr></tbody></table><div class="grid" style="margin-top:16px"><div class="field"><label>Adjustment +/-</label><input id="adj" name="adjustment" type="number" step=".01" value="0"></div><div class="field"><label>Tax amount</label><input id="tax" name="tax_amount" type="number" min="0" step=".01" value="0"></div><div class="field"><label>Total</label><input id="total" readonly value="0.00"></div></div></div><div class="card"><div class="field"><label>Narration</label><textarea name="narration" placeholder="Our Professional charges&#10;Professional fees for legal support..."></textarea></div></div><div class="card"><h2 style="font:500 24px Georgia,serif">Remittance instructions</h2><div class="grid"><div class="field"><label>Bank</label><input name="bank_name" value="Indian Bank"></div><div class="field"><label>Account</label><input name="bank_account" value="7592639814"></div><div class="field"><label>Branch</label><input name="bank_branch" value="kanganheri (New Delhi)"></div><div class="field"><label>IFSC</label><input name="bank_ifsc" value="IDIB000K568"></div><div class="field"><label>PAN</label><input name="pan" value="BNEPG8812Q"></div></div></div><div class="actions"><a class="btn" href="<?=site_url('admin/invoices')?>">Cancel</a><button class="btn primary">Create Invoice →</button></div></form></div><script>const rows=document.getElementById('rows');const flatMode=document.getElementById('flatMode');function syncMode(){const flat=flatMode.checked;document.querySelectorAll('.q,.r').forEach(i=>{i.disabled=flat;i.style.opacity=flat?.45:1});document.querySelectorAll('.m').forEach(i=>{i.disabled=!flat;i.style.opacity=flat?1:.45});calc()}function calc(){let t=0;rows.querySelectorAll('tr').forEach(x=>{let a=flatMode.checked?(+x.querySelector('.m').value||0):(+x.querySelector('.q').value||0)*(+x.querySelector('.r').value||0);t+=a;x.querySelector('.a').textContent=a.toFixed(2)});t+=(+adj.value||0)+(+tax.value||0);total.value=t.toFixed(2)}document.addEventListener('input',calc);flatMode.addEventListener('change',syncMode);add.onclick=()=>{let x=rows.rows[0].cloneNode(true);x.querySelectorAll('input').forEach(i=>{i.value=i.classList.contains('q')?'1':''});x.querySelector('.a').textContent='0.00';rows.appendChild(x);syncMode()};rows.addEventListener('click',e=>{if(e.target.classList.contains('del')&&rows.rows.length>1){e.target.closest('tr').remove();calc()}});user.onchange=e=>{let o=e.target.selectedOptions[0];if(o.dataset.name){name.value=o.dataset.name;email.value=o.dataset.email||''}};syncMode();</script></body></html>
